# [SAME-SCENARIO] stream_microphone.py\n# Streams raw microphone audio and yields interim transcripts using IBM Watson Speech to\n# Text WebSocket. Provider credentials are read from environment variables.\n\nimport asyncio\nimport json\nimport os\nimport sys\nfrom ibm_watson import SpeechToTextV1\nfrom ibm_watson.websocket import RecognizeCallback, AudioSource\n\nclass WatsonMicrophoneStream:\n    def __init__(self, apikey: str, url: str):\n        self.speech_to_text = SpeechToTextV1(\n            auth_type='iam',\n            apikey=apikey,\n            url=url,\n        )\n\n    async def run(self):\n        url = self.speech_to_text._service.url  # endpoint URL\n        # Create WebSocket RecognizeCallback\n        recognize_callback = RecognizeCallback(\n            self._on_connect,\n            self._on_data,\n            self._on_error,\n            self._on_close,\n            audio_format='audio/l16;rate=16000',\n        )\n\n        # Create an AudioSource that reads microphone audio (placeholder)\n        async def audio_generator():\n            # Use sounddevice to capture audio in realtime\n            import sounddevice as sd\n            async def generator():\n                with sd.InputStream(samplerate=16000, channels=1, callback=sd.CallbackFlags):\n                    while True:\n                        data = sd.rec(1024, samplerate=16000, channels=1, blocking=True)\n                        yield data.tobytes()\n            return generator()\n\n        # Run the WebSocket\n        asyncio.create_task(recognize_callback.recognize(url, audio_generator()))\n        await asyncio.Event().wait()  # keep script alive\n\n    def _on_connect(self):\n        print('Connected to Watson STT')\n\n    def _on_data(self, json_data):\n        # Called for each interim / final result\n        results = json.loads(json_data)\n        for result in results.get('results', []):\n            alternatives = result.get('alternatives', [])\n            if alternatives:\n                interim = alternatives[0].get('transcript', '')\n                print('Interim:', interim)\n            else:\n                print('No alternatives')\n\n    def _on_error(self, error):\n        print('Error:', error)\n\n    def _on_close(self):\n        print('WebSocket closed')\n\nif __name__ == '__main__:\n    apikey = os.getenv('IBM_STT_APIKEY')\n    url = os.getenv('IBM_STT_URL')\n    if not apikey or not url:\n        print('Set IBM_STT_APIKEY and IBM_STT_URL env vars')\n        sys.exit(1)\n    stream = WatsonMicrophoneStream(apikey, url)\n    asyncio.run(stream.run())\n